import {CFG,ITEMS,LAUNCHERS,ROUTES,ROLES,PEOPLE,SOURCES} from './data.js';
import * as E from './engine.js';import {MAPS,visibleObjects,nearObject,move,enter,blocked,newStory,remember,validStory} from './world.js';import {drawWorld} from './world-render.js';import {ChipAudio} from './audio.js';
const root=document.querySelector('#root'),audio=new ChipAudio();let s=null,saved=null,title=true,talk=null,menu=null,path=[],walkTo=null,dir=0,last=0,saveClock=0,toastText='',toastUntil=0,cam={ox:0,oy:0},cinema=0;const keys=new Set();
try{saved=JSON.parse(localStorage.getItem('beeyond-rpg13'));if(!validStory(saved,E.validSave))saved=null;if(saved)saved.lang='en';}catch{}
const tr=(es,en)=>((s?.lang||saved?.lang||'en')==='es'?es:en);const loc=a=>a[(s?.lang||'en')==='es'?0:1];const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const btn=(text,action,cls='',disabled=false)=>`<button data-do="${action}" class="${cls}" ${disabled?'disabled':''}>${text}</button>`;
const names={chamberA:['Cámara económica','Economy chamber'],chamberB:['Cámara Vanguard','Vanguard chamber'],panels:['Alas solares','Solar wings'],thermal:['Sensor térmico','Thermal sensor'],toolkit:['Kit de reparación','Repair toolkit'],antenna:['Antena de alta ganancia','High-gain antenna'],backup:['Enlace de respaldo','Backup link'],dosimeter:['Dosímetro','Dosimeter']};
function save(){saved=structuredClone(s);try{localStorage.setItem('beeyond-rpg13',JSON.stringify(s));}catch{toast(tr('No se pudo guardar en este navegador.','This browser could not save your progress.'));}}
function toast(text){toastText=text;toastUntil=performance.now()+4000;render();}
function say(who,text,choices=null,face=null){keys.clear();path=[];walkTo=null;menu=null;talk={who,text,choices:choices||[[tr('Continuar','Continue'),'dismiss']],face,start:performance.now(),lastChar:0};render();}
function open(id){keys.clear();path=[];walkTo=null;talk=null;menu=id;render();}
function close(){talk=null;menu=null;keys.clear();render();}
function changeMap(id,at){enter(s,id,at);path=[];walkTo=null;keys.clear();save();render(true);}
function memory(id){remember(s,id);save();}
const memories={notebook:['El cuaderno fuera de la caja','The notebook out of the box'],plant:['La última planta sigue aquí','The last plant is still here'],letter:['Alguien creyó en la pregunta','Someone believed in the question'],Pip:['Una radio, arreglada entre dos','A radio repaired together'],Nim:['Esperar junto al semillero','Waiting beside the flowers'],Eko:['Un mensaje sin esconder las dudas','A message with room for doubt'],promise:['Una promesa demasiado grande','A promise too large'],bench:['Cuatro lugares en el banco','Four places on the bench'],care:['Escuchar una vida pequeña','Listening to a small life'],arrival:['Un punto rojo convertido en lugar','A red dot becomes a place'],garden:['La primera flor de otro comienzo','The first flower of another beginning']};
function join(name){if(!s.friends.includes(name)){s.friends.push(name);s.mission.friends=[...s.friends];memory(name);}save();}
function objective(){if(!s.flags.notebookPlaced)return tr('Saca el cuaderno de la caja y déjalo en el escritorio.','Take the notebook from the box and place it on the desk.');if(!s.flags.plantWatered)return tr('La planta junto a la pared lleva días sin agua.','The plant beside the wall has gone days without water.');if(!s.flags.grant)return tr('Alguien dejó una carta junto a la puerta.','Someone left a letter by the door.');if(s.friends.length<3)return tr('Pip está en el taller; Nim, en el jardín; Eko, en la estación. No tienes que ir en ese orden.','Pip is in the workshop, Nim in the garden, Eko at the station. Visit in any order.');if(s.mission.phase==='lab')return tr('En el laboratorio: cámara, instrumentos, mapa y reunión. El cohete espera al fondo.','In the lab: chamber, instruments, map and team meeting. The rocket waits beyond.');if(s.mission.phase==='voyage')return s.mission.flight.pending?tr('La nave necesita atención. Acércate a sus sistemas.','The ship needs attention. Check its systems.'):tr('Puedes visitar al equipo y a las abejas antes de volver al puesto de mando.','Visit the crew and bees before returning to the helm.');return tr('Lo que aprendas también merece volver a casa.','What you learn deserves to make it home too.');}
function checkLetter(){if(s.flags.notebookPlaced&&s.flags.plantWatered&&!s.flags.letterArrived){s.flags.letterArrived=true;audio.effect('advance');say(tr('Toc, toc.','Knock, knock.'),tr('El ruido viene de la puerta.\nUn sobre se desliza por debajo.','The sound comes from the door.\nAn envelope slides underneath.'));}save();}
function interact(o){if(!o)return;audio.effect();if(o.to){if(s.map==='home'&&!s.flags.grant)return say('Lum',tr('Antes de irme… algo quedó sin cerrar aquí.','Before I leave… something is unfinished here.'));if(o.id==='lab'&&s.friends.length<3){changeMap(o.to,o.at);return say('Lum',tr('La mesa sigue puesta para cuatro.\nTodavía tengo a quién buscar.','The table is still set for four.\nThere are people I still need to find.'));}return changeMap(o.to,o.at);}const id=o.id;
if(s.map==='home'){
if(s.flags.finalKind&&id==='desk')return finish();
if(id==='box'){if(s.flags.notebookPlaced)return say('Lum',tr('La caja ya no parece una despedida.','The box no longer feels like goodbye.'));if(s.carry)return say('Lum',tr('El cuaderno me cabe en las manos.\nTal vez todavía tenga un lugar en el escritorio.','The notebook fits in my hands.\nMaybe it still belongs on the desk.'));return say(tr('Una caja sin cerrar','An unpacked box'),tr('Entre recibos y borradores está tu cuaderno.\nTiene una semilla dibujada en la tapa.','Between receipts and drafts lies your notebook.\nThere is a seed drawn on its cover.'),[[tr('Sacarlo de la caja','Take it out'),'take-notebook'],[tr('Dejarlo por ahora','Leave it for now'),'dismiss']]);}
if(id==='desk'){if(s.carry==='notebook')return say('Lum',tr('Hay una marca limpia en el polvo.\nExactamente del tamaño del cuaderno.','There is a clean patch in the dust.\nExactly the size of the notebook.'),[[tr('Dejar el cuaderno aquí','Place the notebook here'),'place-notebook']]);return say('Lum',s.flags.notebookPlaced?tr('La página sigue abierta en la misma pregunta.\nEsta vez, no la cierro.','The page is still open at the same question.\nThis time I leave it open.'):tr('Una taza fría. Un lápiz sin punta.\nEl espacio donde antes trabajaba.','A cold cup. A blunt pencil.\nThe space where I used to work.'));}
if(id==='plant')return say('Lum',s.flags.plantWatered?tr('Las hojas todavía están inclinadas.\nLas cosas no mejoran todas al mismo tiempo.','The leaves are still leaning.\nNot everything gets better at once.'):tr('Queda un poco de agua en la jarra.\nLa planta no sabe que hoy pensaba rendirme.','There is a little water left in the jug.\nThe plant does not know I meant to give up today.'),s.flags.plantWatered?null:[[tr('Regarla despacio','Water it slowly'),'water-plant']]);
if(id==='letter')return say('Aurelia',tr('Lum:\nTu pregunta merece una oportunidad. Te concedemos 2.000 créditos para investigar el transporte de reinas de abejorro en diapausa. Dos revisiones pueden aportar 150 y 200 más.\nEl fondo es de alto riesgo: un fracaso podrá costarnos el laboratorio. Si la misión funciona, habrá una oportunidad de seguir investigando.','Lum,\nYour question deserves a chance. We award you 2,000 credits to investigate dormant bumblebee transport. Two design reviews can add another 150 and 200.\nThis is high-risk funding: failure may cost us the laboratory. If the mission works, there will be a chance to keep researching.'),[[tr('Guardar la carta en el cuaderno','Keep the letter in the notebook'),'accept-letter']]);
if(id==='bed')return say('Lum',s.flags.grant?tr('Puedo descansar sin renunciar.','I can rest without giving up.'):tr('Mañana iba a llevarme las cajas.','Tomorrow I was going to take the boxes away.'));
return say('Lum',tr('Un libro tiene una flor seca entre las páginas.\nNim dijo que así no se perdían del todo.','A book holds a pressed flower.\nNim said this way they were never entirely lost.'));}
if(s.map==='town'){if(id==='bench'){if(s.friends.length===3){memory('bench');return say(tr('Un banco para cuatro','A bench for four'),tr('Antes se sentaban aquí después del laboratorio.\nPip dejó una taza de repuesto. Nim, una semilla. Eko, espacio a su lado.','You used to sit here after the lab.\nPip left a spare cup. Nim left a seed. Eko left room beside them.'));}return say('Lum',tr('Cuatro marcas en la madera.\nReconozco dónde se sentaba cada quien.','Four marks in the wood.\nI remember where everyone used to sit.'));}return say('Lum',id==='pond'?tr('La superficie tarda en quedarse quieta.','The surface takes time to become still.'):tr('El pueblo siguió creciendo mientras yo miraba la misma página.','The village kept growing while I stared at the same page.'));}
if(s.map==='workshop'){
if(id==='switch')return say('Pip',s.radioOn?tr('Está encendida. Para abrirla, primero cortamos la corriente.','It is on. Before opening it, we turn off the power.'):tr('Sin corriente. Ahora podemos revisar el conector.','Power is off. Now we can inspect the connector.'),[[s.radioOn?tr('Apagar','Switch off'):tr('Encender','Switch on'),'radio-switch']],0);
if(id==='radio'){if(s.radioOn&&!s.radioFixed)return say('Pip',tr('Todavía tiene corriente.\nEl interruptor está a la izquierda.','It is still powered.\nThe switch is on the left.'),null,0);if(!s.radioFixed)return say('Pip',tr('Sostén este extremo. Yo encajo el otro.\nNo hace falta que lo arregles todo sin ayuda.','Hold this end. I will fit the other.\nYou do not have to fix everything alone.'),[[tr('Sostener el cable','Hold the cable'),'radio-fix']],0);return say('Pip',s.radioOn?tr('Una melodía atraviesa la estática.\nPip lleva el ritmo con un dedo.','A melody comes through the static.\nPip taps along with one finger.'):tr('El cable está firme. Probemos el interruptor.','The cable is secure. Let us try the switch.'),null,0);}
if(id==='Pip'){if(s.friends.includes('Pip'))return say('Pip',tr('La mesa del laboratorio todavía tiene mi silla, ¿verdad?','My chair is still at the lab table, right?'),null,0);if(!s.radioFixed||!s.radioOn)return say('Pip',tr('Te iba a escribir. Pero esta radio…\n¿Me ayudas a devolverle la voz?','I was going to write to you. But this radio…\nWill you help me give it its voice back?'),null,0);return say('Pip',tr('Así que Aurelia respondió.\n¿Y tú? ¿Cómo estás de verdad?','So Aurelia answered.\nAnd you? How are you, really?'),[[tr('Me da miedo volver a fallar','I am afraid to fail again'),'pip-honest'],[tr('Necesito tu ayuda','I need your help'),'pip-help']],0);}
return say('Pip',tr('La herramienta más gastada es la que más gente ha usado.','The most worn tool is the one most people have shared.'),null,0);}
if(s.map==='garden'){
if(id==='flowers')return say('Nim',s.flags.flowersWatered?tr('El agua se va despacio entre la tierra.\nNo hay que apurar una raíz.','Water slowly sinks into the soil.\nThere is no need to hurry a root.'):tr('La regadera está al lado.\nMientras hablamos, podríamos darles un poco de agua.','The watering can is nearby.\nWhile we talk, we could give them some water.'),s.flags.flowersWatered?null:[[tr('Regar el semillero','Water the flower bed'),'water-flowers']],1);
if(id==='hive'){s.flags.observed=true;memory('care');return say('Nim',tr('Mira cómo vuelve a la misma flor.\nAntes de medir algo, a veces hay que aprender a quedarse mirando.','Look how it returns to the same flower.\nBefore measuring something, sometimes we must learn to stay and watch.'),[[tr('Quedarme un momento','Stay a moment'),'watch-bees']],'bee');}
if(id==='Nim'){if(s.friends.includes('Nim'))return say('Nim',tr('Llevaré el cuaderno de campo.\nNo solo anotamos lo que sale bien.','I will bring the field notebook.\nWe do not only record what goes well.'),null,1);if(!s.flags.flowersWatered||!s.flags.observed)return say('Nim',tr('Me alegra verte aquí.\nAntes de hablar de Marte, ven a ver lo que pasa en este jardín.','I am glad you came.\nBefore we talk about Mars, come see what is happening in this garden.'),null,1);join('Nim');return say('Nim',tr('Puedo ir contigo. Pero hay algo que quiero que prometamos:\nsi no sabemos algo, lo escribimos. También eso es cuidar.','I can come with you. But let us promise one thing:\nwhen we do not know something, we write it down. That is care too.'),null,1);}
return say(tr('Cuaderno de campo','Field notebook'),tr('Bombus terrestris. Diapausa estudiada en la Tierra.\nSobrevivir aquí no demuestra que puedan hacerlo en el espacio.\nNim subrayó: “preguntar antes de prometer”.','Bombus terrestris. Diapause studied on Earth.\nSurviving here does not demonstrate survival in space.\nNim underlined: “ask before promising”.'));}
if(s.map==='station'){
if(id==='message')return say('Eko',tr('Aurelia pregunta qué esperamos encontrar.\nEl cursor parpadea al final de una frase que todavía puedes cambiar.','Aurelia asks what we hope to find.\nThe cursor blinks at the end of a sentence you can still change.'),[[tr('Explicar la pregunta y nuestras dudas','Explain the question and our doubts'),'message-honest'],[tr('Prometer que las abejas sobrevivirán','Promise the bees will survive'),'message-promise']],2);
if(id==='Eko'){if(s.friends.includes('Eko'))return say('Eko',s.flags.honest?tr('Guardé una copia.\nLa parte donde dijiste “todavía no sabemos” me dio confianza.','I kept a copy.\nThe part where you said “we do not know yet” gave me confidence.'):tr('Podemos corregir ese mensaje.\nNo hace falta fingir certeza para merecer una oportunidad.','We can correct that message.\nYou do not need to pretend certainty to deserve a chance.'),null,2);if(!s.flags.messageSent)return say('Eko',tr('Tus últimos mensajes eran muy cortos.\nMe alegra que hoy hayas venido en persona. ¿Escribimos a Aurelia?','Your last messages were very short.\nI am glad you came in person today. Shall we write to Aurelia?'),null,2);join('Eko');return say('Eko',tr('Iré. Y escucharé.\nIncluso cuando la respuesta tarde en llegar.','I will come. And I will listen.\nEven when the answer takes time to arrive.'),null,2);}
return say('Eko',tr('Desde aquí, Marte parece quieto.\nTodo lo que vamos a calcular ocurre mientras se mueve.','From here, Mars looks still.\nEverything we will calculate happens while it moves.'),null,2);}
if(s.map==='lab'){
if(['bio','engineering','comms'].includes(id)){const role={bio:1,engineering:0,comms:2}[id];if(s.mission.players>1&&s.mission.role!==role)return say(PEOPLE[role],tr('Pasemos el dispositivo. Esta parte la decide nuestro equipo de ','Pass the device. This decision belongs to ')+ROLES[role],[[tr('Tomar este turno','Take this turn'),'role:'+role+':'+id]],role);s.mission.role=role;return open(id);}
if(id==='chart'||id==='review'||id==='launch'){if(s.mission.players>1&&s.mission.role!==3)return say('Lum',tr('Reunamos las decisiones antes de elegir el rumbo.','Let us bring our decisions together before choosing our course.'),[[tr('Tomar el turno de dirección','Take the mission lead turn'),'role:3:'+id]],3);s.mission.role=3;}
if(id==='chart')return open('chart');
if(id==='review'){if(s.friends.length<3)return say('Lum',tr('La mesa está lista. Faltan mis amistades.','The table is ready. My friends are not here yet.'));return open('review');}
if(id==='launch'){if(s.friends.length<3)return say('Lum',tr('No quiero ir sin hablar con todo el equipo.','I do not want to leave before speaking with everyone.'));if(E.milestone(s.mission)<4)return open('review');return say('Lum',tr('En el bolsillo está la carta.\nAl otro lado de la puerta, el equipo espera.\n¿Nos vamos?','The letter is in your pocket.\nBeyond the door, the team is waiting.\nShall we go?'),[[tr('Subir con el equipo','Board with the team'),'launch'],[tr('Volver a revisar','Check once more'),'dismiss']]);}}
if(s.map==='ship'){
if(id==='helm'){if(s.mission.flight.pending)return say('Eko',tr('Podemos esperar aquí.\nLa alarma está en el panel de sistemas.','We can wait here.\nThe alarm is at the systems panel.'),null,2);return say('Lum',tr('Otra página del viaje.\nAntes de avanzar, puedes visitar a las abejas o hablar con el equipo.','Another page of the journey.\nBefore moving on, you can visit the bees or talk with the crew.'),[[tr('Continuar el viaje','Continue the voyage'),'advance'],[tr('Quedarme un momento','Stay a moment'),'dismiss']]);}
if(id==='repair')return s.mission.flight.pending?open('incident'):say('Pip',tr('Nada urgente por ahora.\nQue algo funcione también merece atención.','Nothing urgent for now.\nSomething that works deserves attention too.'),null,0);
if(id==='chamber'){s.careDay=s.mission.day;memory('care');const f=s.mission.flight;return say('Nim',tr('La cámara responde con una luz tenue.\n','The chamber answers with a soft light.\n')+`${f.temp.toFixed(1)} °C · ${f.humidity.toFixed(0)}% HR · ${tr('índice de riesgo','risk index')} ${f.risk.toFixed(0)}/100.\n`+tr('Anotas las cifras. No las conviertes en una promesa.','You record the numbers. You do not turn them into a promise.'),null,'bee');}
if(id==='Pip')return say('Pip',s.mission.flight.decisions.some(d=>d.type==='mechanical')?tr('Ya hemos arreglado dos cosas muy lejos de casa.\nLa primera fue una radio.','We have repaired two things far from home.\nThe first was a radio.'):tr('Traje el conector viejo.\nNo sirve de repuesto. Me recuerda que supimos arreglar algo.','I brought the old connector.\nIt is not a spare. It reminds me that we could fix something.'),null,0);
if(id==='Nim')return say('Nim',tr('No hace falta abrir la cámara para demostrar que nos importan.\nA veces cuidar es mantener una distancia.','We do not need to open the chamber to show we care.\nSometimes care means keeping a distance.'),null,1);
return say('Eko',s.flags.honest?tr('Aurelia respondió a nuestro mensaje:\n“Gracias por escribir también lo que no saben”.','Aurelia answered our message:\n“Thank you for writing down what you do not know, too”.'):tr('Aurelia pregunta por la garantía que prometimos.\nPodemos responder con los datos, y corregir lo que dijimos.','Aurelia asks about the guarantee we promised.\nWe can answer with the data, and correct what we said.'),s.flags.honest?null:[[tr('Enviar la corrección','Send a correction'),'correct-message']],2);}
if(s.map==='mars'){if(id==='memory'){if(s.mission.phase==='epilogue')return ending();return say('Lum',tr('La carta está doblada en los mismos cuatro lugares.\nTodavía huele un poco a casa.','The letter is folded in the same four places.\nIt still smells a little like home.'));}const steps=['habitat','climate','seedbed','transmit'];if(s.mission.phase==='epilogue')return say('Nim',tr('La flor queda aquí. Lo aprendido puede viajar.','The flower stays here. What we learned can travel.'),null,'bee');if(steps[s.mission.green.step]!==id)return say('Nim',tr('Primero preparemos ','First, let us prepare ')+loc(MAPS.mars.objects.find(o=>o.id===steps[s.mission.green.step]).label)+'.',null,1);return open('green');}
}
function ending(){const good=s.mission.green.colony>=60&&s.mission.green.lights;const lines=good?[
tr('Una flor se abre dentro del hábitat sellado.\nNadie dice nada durante un momento.','A flower opens inside the sealed habitat.\nFor a moment, nobody speaks.'),
tr('Muchos años después, en el futuro imaginado de esta historia, nuevos estudios reciben un Nobel.\nLum busca a sus amistades entre el público.','Many years later, in this story’s imagined future, further studies receive a Nobel Prize.\nLum searches for their friends in the audience.'),
tr('Pip levanta el conector viejo. Nim guarda una semilla. Eko sonríe.\nLum saca la primera carta.\n“No llegué hasta aquí por mi cuenta”.','Pip raises the old connector. Nim holds a seed. Eko smiles.\nLum unfolds the first letter.\n“I did not get here on my own”.')]:[tr('El jardín todavía no está listo para florecer.\nEl equipo anota lo que falta y prepara otro experimento.','The garden is not ready to bloom.\nThe team records what is missing and prepares another experiment.'),tr('La carta de Aurelia queda junto al nuevo cuaderno.\nUna oportunidad no tiene por qué ser la última.','Aurelia’s letter rests beside the new notebook.\nOne chance does not have to be the last.')];say(tr('Lo que trajimos','What we carried'),lines[Math.min(s.ending,lines.length-1)],[[s.ending<lines.length-1?tr('Escuchar','Listen'):tr('Quedarme en el jardín','Stay in the garden'),s.ending<lines.length-1?'ending-next':'dismiss'],[tr('Abrir el cuaderno','Open the notebook'),'journal']]);}
function verdict(){const r=E.report(s.mission);if(r.arrived){memory('arrival');say('Eko',tr('Marte ya no es un punto en el mapa.\nLa nave llegó. Ahora debemos preguntar qué significa eso, y qué todavía no demuestra.','Mars is no longer a dot on the map.\nThe ship arrived. Now we must ask what that means, and what it still does not prove.'),[[tr('Leer los resultados juntos','Read the results together'),'results']],2);}else say('Nim',tr('Esta vez no llegamos.\nNo voy a guardar tu cuaderno en una caja. Volvamos a la mesa.','This time we did not arrive.\nI am not putting your notebook back in a box. Let us return to the table.'),[[tr('Entender qué pasó','Understand what happened'),'results']],1);}
import {assessment} from './assessment.js';
function diagnostics(){const g=s.mission,t=E.stats(g),l=E.launcher(g),r=E.route(g),out=[];if(!g.parts.some(id=>E.item(id).kind==='chamber'))out.push(tr('Falta una cámara biológica.','A biological chamber is missing.'));if(!g.parts.some(id=>['antenna','backup'].includes(id)))out.push(tr('Falta una vía de comunicación.','A communications link is missing.'));if(t.kg>l.cap)out.push(`${t.kg.toFixed(1)} / ${l.cap} kg: `+tr('demasiada masa.','too much mass.'));if(t.use>t.arrival)out.push(tr('Potencia al llegar insuficiente: ','Insufficient arrival power: ')+`${t.arrival.toFixed(0)} W / ${t.use} W.`);if(t.dv<r.dv)out.push(tr('Delta-v insuficiente: ','Insufficient delta-v: ')+`${t.dv.toFixed(2)} / ${r.dv}.`);return out;}
function schematic(){const parts=s.mission.parts;return `<svg viewBox="0 0 80 160" role="img" aria-label="${tr('Esquema de la nave','Ship schematic')}"><path d="M40 3L58 30V128H22V30Z" fill="#d5d6bc" stroke="#7f9da6" stroke-width="3"/><path d="M26 48H54V105H26Z" fill="#19354b"/>${parts.some(id=>id.startsWith('chamber'))?'<rect x="29" y="55" width="22" height="27" fill="#e3bd65"/><rect x="32" y="59" width="16" height="17" fill="#8bbebb"/>':''}${parts.includes('panels')?'<path d="M2 65H20V107H2ZM60 65H78V107H60Z" fill="#5f8cba" stroke="#b8cdbd"/>':''}${parts.includes('antenna')?'<path d="M40 26V13M31 14Q40 25 49 14" stroke="#e4bb72" stroke-width="3" fill="none"/>':''}${parts.includes('toolkit')?'<rect x="29" y="88" width="22" height="10" fill="#b97b67"/>':''}<path d="M22 106L11 137H24M58 106L69 137H56M31 128V138H49V128" fill="#a88069"/></svg>`;}
function menuHTML(){const g=s.mission,t=E.stats(g);let html='',wide=false;const back=btn(tr('Volver','Back'),'dismiss','small');
if(['bio','engineering','comms'].includes(menu)){wide=true;const role={bio:1,engineering:0,comms:2}[menu];html=`<h2>${tr('Una nave hecha de decisiones','A ship made of decisions')}</h2><div class="assembly"><div class="rows">${ITEMS.filter(i=>i.role===role).map(i=>`<div class="row"><strong>${loc(names[i.id])}</strong><p>${i.cost} cr · ${i.kg} kg · ${i.gen?'+'+i.gen:i.w} W</p><small>${tr('Penalización de masa','Mass penalty')}: ${(i.kg*CFG.dvPerKg).toFixed(4)} km/s</small>${btn(g.parts.includes(i.id)?tr('Retirar','Remove'):tr('Instalar','Install'),'item:'+i.id,g.parts.includes(i.id)?'':'primary')}</div>`).join('')}</div><div class="schematic">${schematic()}<small>${tr('Las piezas instaladas cambian el esquema.','Installed equipment changes the schematic.')}</small></div><div><span class="eyebrow">${tr('Fondos Aurelia','Aurelia funds')}</span><h3>${t.budget} cr</h3><p class="rpg-status">${t.kg.toFixed(1)} / ${E.launcher(g).cap} kg<br>${t.use} / ${t.power} W<br>Δv ${t.dv.toFixed(2)} km/s</p><small>${tr('Potencia al llegar','Arrival power')}: ${t.arrival.toFixed(0)} W. ${tr('Factor 0,85 simplificado.','Simplified 0.85 factor.')}</small>${diagnostics().map(e=>`<p class="notice bad">${e}</p>`).join('')||'<p>✓</p>'}<p class="rpg-small">${tr('El dinero, la masa y la potencia pertenecen a todo el equipo.','Money, mass and power belong to the whole team.')}</p></div></div>`;}
else if(menu==='chart')html=`<h2>${tr('Dos caminos hasta Marte','Two paths to Mars')}</h2>${ROUTES.map((r,i)=>`<div class="row"><div><strong>${tr(i===0?'Transferencia estándar':'Transferencia rápida',r.name)}</strong><p>${r.days} ${tr('días','days')} · ${r.dv} km/s<br>${r.depart} → ${r.arrive}</p></div>${btn(g.route===r.id&&g.compared.includes(r.id)?'✓':tr('Comparar y elegir','Compare and choose'),'route:'+r.id)}</div>`).join('')}<h3 class="rpg-subhead">${tr('Paquete de lanzamiento','Launch package')}</h3>${LAUNCHERS.map(l=>`<div class="row"><div><strong>${l.name}</strong><p>${l.cost} cr · ${l.cap} kg · ${l.power} W<br>${tr('Consumo del bus','Bus use')} ${l.overhead} W · Δv ${l.dv}</p></div>${btn(g.launcher===l.id?'✓':tr('Elegir','Choose'),'launcher:'+l.id)}</div>`).join('')}<small>${tr('Escenarios transcritos del proyecto y atribuidos a NASA Ames. Falta verificar su consulta original.','Scenarios transcribed from the project and attributed to NASA Ames. The original query remains unverified.')}</small>`;
else if(menu==='review')html=`<h2>${tr('La mesa está completa','Everyone is at the table')}</h2><p>${tr('Pip mira la potencia. Nim, la cámara. Eko, el enlace. Tú abres el presupuesto.','Pip checks power. Nim checks the chamber. Eko checks the link. You open the budget.')}</p><p class="rpg-status">CML ${E.milestone(g)} / 4 · ${t.budget} cr · ${t.kg.toFixed(1)} kg · ${t.use}/${t.power} W</p><div class="row"><p>${tr('CML 1: una pregunta científica','CML 1: a scientific question')}</p>✓</div><div class="row"><p>${tr('CML 2: cámara dentro de masa y potencia','CML 2: chamber within mass and power')} · +150 cr</p>${btn(g.grants.includes(0)?'✓':tr('Revisar','Review'),'grant:0','',g.grants.includes(0))}</div><div class="row"><p>${tr('CML 3: comparar dos rutas','CML 3: compare two routes')} · +200 cr</p>${btn(g.grants.includes(1)?'✓':tr('Revisar','Review'),'grant:1','',g.grants.includes(1))}</div><div class="memo">${diagnostics().join('<br>')||tr('CML 4: diseño compatible. Podemos ir al cohete.','CML 4: compatible design. We can go to the rocket.')}</div><small>${tr('Hitos inspirados en JPL; créditos y aprobación son reglas del juego.','JPL-inspired milestones; funding and approval are game rules.')}</small>`;
else if(menu==='incident')html=`<h2>${tr('La nave necesita una decisión','The ship needs a decision')}</h2><p>${tr({thermal:'La cámara se está calentando.',comms:'La señal se pierde entre la estática.',mechanical:'Una vibración nueva recorre el casco.'}[g.flight.pending],{thermal:'The chamber is warming.',comms:'The signal is lost in static.',mechanical:'A new vibration travels through the hull.'}[g.flight.pending])}</p><p class="rpg-status" id="timer">${g.timer?Math.ceil(g.remaining)+' s':tr('Sin límite de tiempo','Untimed')}</p>${E.options(g).map(o=>{const nm={repair:['Usar una reparación','Use a repair'],battery:['Pulso de refrigeración','Cooling pulse'],wait:['Esperar','Wait'],align:['Reorientar la antena','Realign the antenna'],essential:['Priorizar telemetría esencial','Prioritize essential telemetry'],power:['Aislar con batería','Isolate with battery'],continue:['Seguir sin reparar','Continue without repair']}[o.id];const ds={repair:tr('Consume una carga del kit.','Uses one repair charge.'),battery:tr('−600 Wh; +12 riesgo.','−600 Wh; +12 risk.'),wait:tr('+6 °C; −12% HR; +35 riesgo y fuga persistente.','+6 °C; −12% RH; +35 risk and persistent leak.'),align:tr('+12 días de viaje; conserva observaciones.','+12 travel days; keeps observations.'),essential:tr('Descarta memoria pendiente; reduce futuras observaciones a la mitad.','Discards buffered data; halves future observations.'),power:tr('−500 Wh; −20 integridad; detiene el daño.','−500 Wh; −20 integrity; stops damage.'),continue:tr('−15 integridad y −10 por cada 30 días.','−15 integrity and −10 per 30 days.')}[o.id];return `<div class="row"><div><strong>${loc(nm)}</strong><p>${ds}</p></div>${btn(tr('Decidir','Choose'),'resolve:'+o.id,'',o.disabled)}</div>`;}).join('')}<small>${tr('Puedes pausar. Si se agota el tiempo: reparación disponible, después batería y, si no hay recursos, aceptar el daño. En comunicaciones: telemetría esencial.','You can pause. Timeout uses a repair, then battery; if unavailable it accepts damage. Communications fallback: essential telemetry.')}</small>`;
else if(menu==='results'){const a=assessment(g),f=g.flight;html=`<h2>${tr('Lo que ocurrió, y por qué','What happened, and why')}</h2><p class="rpg-status">${a.score} / 100 · ${g.day} ${tr('días','days')} · ${f.sent.toFixed(1)} MB</p><div class="row"><p>${tr('Configuración','Configuration')}</p><strong>${a.configuration}/40</strong></div><div class="row"><p>${tr('Respuestas a incidentes','Incident responses')}</p><strong>${a.decisions}/40</strong></div><div class="row"><p>${tr('Reservas y presupuesto','Reserves and budget')}</p><strong>${a.resources}/20</strong></div>${a.limited?`<small>${tr('El resultado técnico limita la nota: fallo vital, máximo 49; llegada comprometida, máximo 79.','Technical outcome caps the score: vital failure at 49; compromised arrival at 79.')}</small>`:''}<p>${tr('Datos perdidos','Lost data')}: ${f.lost.toFixed(1)} MB · ${tr('riesgo','risk')} ${f.risk.toFixed(0)}/100 · ${tr('integridad','integrity')} ${f.integrity.toFixed(0)}/100.</p><p>${tr('Próximo intento: ','Next attempt: ')}${f.risk>35?tr('mejora el control térmico o reserva una reparación.','improve thermal control or reserve a repair.'):f.lost>0?tr('compara transmisión y almacenamiento.','compare transmission and storage.'):f.integrity<80?tr('lleva herramientas y conserva energía de emergencia.','bring tools and reserve emergency energy.'):tr('cambia una sola pieza y compara usando la misma semilla.','change one part and compare using the same seed.')}</p><div class="actions">${E.report(g).arrived?btn(tr('Imaginar el invernadero','Imagine the greenhouse'),'green','primary'):btn(tr('Ver el desenlace','See the ending'),'finish','primary')}${btn(tr('Rediseñar','Redesign'),'redesign')}${btn(tr('Exportar bitácora','Export log'),'download')}</div><small>${tr('Modelo educativo hipotético. Riesgo no es probabilidad de supervivencia.','Hypothetical educational model. Risk is not a survival probability.')}</small>`;}
else if(menu==='green'){const step=g.green.step;const qs=[['Despertar despacio','Wake slowly'],['Estabilizar el ambiente','Stabilize the habitat'],['Encender luces de cultivo','Switch on growing lights'],['Compartir métodos y resultados','Share methods and results']];html=`<h2>${loc(qs[step])}</h2><p>${tr('Reserva del hábitat','Habitat reserve')}: ${g.green.cells} · ${tr('índice de colonia','colony index')}: ${g.green.colony.toFixed(0)}</p><p>${step<3?tr('La opción cuidadosa consume una unidad de la reserva. La alternativa rápida conserva recursos, pero reduce el índice de colonia.','The careful option uses one reserve unit. The quick option preserves resources but lowers the colony index.'):tr('La investigación también incluye lo que no pudimos demostrar.','Research includes what we could not demonstrate, too.')}</p><div class="actions">${btn(tr('Hacerlo con cuidado','Take care'),'green-choice:care','primary',step<3&&g.green.cells<1)}${btn(tr('Usar la alternativa mínima','Use the minimal alternative'),'green-choice:rush')}</div><small>${tr('Continuación ficticia en un hábitat sellado. No valida vida ni polinización en Marte.','Fictional continuation in a sealed habitat. Does not validate life or pollination on Mars.')}</small>`;}
else if(menu==='journal')html=`<h2>${tr('El cuaderno que no guardaste','The notebook you did not pack away')}</h2><p>${objective()}</p>${s.memories.map(id=>`<div class="memo">${loc(memories[id]||[id,id])}</div>`).join('')}<h3 class="rpg-subhead">${tr('Bitácora de misión','Mission log')}</h3>${g.log.length?g.log.map(l=>`<p class="rpg-small">${l.day} d · ${esc(l.text)}</p>`).join(''):`<p>${tr('Todavía hay páginas en blanco.','There are still blank pages.')}</p>`}<div class="actions">${btn(tr('Fuentes y límites','Sources and limits'),'sources')}${btn(tr('Exportar','Export'),'download')}</div>`;
else if(menu==='sources')html=`<h2>${tr('Preguntar antes de prometer','Ask before promising')}</h2><p>${tr('La masa, los precios, el índice de riesgo y la penalización lineal de delta-v son modelos del juego. La supervivencia interplanetaria de estas reinas no está demostrada. El viaje humano y los premios pertenecen a la ficción.','Mass, prices, risk and linear delta-v penalties are game models. Interplanetary survival of these queens is not demonstrated. Human travel and awards belong to fiction.')}</p>${SOURCES.map(a=>`<div class="memo"><a href="${a.url}" target="_blank" rel="noopener">${a.title}</a><small>${a.kind}</small><p class="rpg-small">${a.use}</p></div>`).join('')}`;
else if(menu==='access')html=`<h2>${tr('Moverse por este lugar','Move around this place')}</h2><p>${tr('Elige un destino: Lum caminará hasta él. También puedes pulsar un objeto en el escenario.','Choose a destination: Lum will walk there. You can also click an object in the scene.')}</p><div class="near-buttons">${visibleObjects(s).map(o=>btn(loc(o.label),'walk:'+o.id)).join('')}</div>`;
else html=`<h2>${tr('Un momento para respirar','A moment to breathe')}</h2><p>${tr('La partida está guardada. Los incidentes están en pausa.','Your progress is saved. Incidents are paused.')}</p><label>${tr('Idioma','Language')}<select id="language"><option value="es" ${s.lang==='es'?'selected':''}>Español</option><option value="en" ${s.lang==='en'?'selected':''}>English</option></select></label><label>${tr('Personas en el mismo dispositivo','Players on this device')}<select id="players">${[1,2,3,4].map(n=>`<option value="${n}" ${g.players===n?'selected':''}>${n}</option>`).join('')}</select></label><label>${tr('Tiempo de respuesta','Response timer')}<select id="time-mode">${[[0,tr('Sin límite · historia','Untimed · story')],[60,'60 s'],[120,'120 s']].map(([n,l])=>`<option value="${n}" ${g.timer===n?'selected':''}>${l}</option>`).join('')}</select></label><label>${tr('Música','Music')}<input data-volume="music" type="range" min="0" max="0.6" step="0.01" value="${audio.music}"></label><label>${tr('Efectos','Effects')}<input data-volume="sfx" type="range" min="0" max="0.8" step="0.01" value="${audio.sfx}"></label><div class="actions">${btn(tr('Pantalla completa','Fullscreen'),'fullscreen')}${btn(tr('Cuaderno','Notebook'),'journal')}${['report','epilogue'].includes(g.phase)?btn(tr('Resultados','Results'),'results'):''}${btn(tr('Volver al título','Return to title'),'title')}</div>`;
return `<div class="rpg-menu" role="dialog" aria-modal="true" aria-label="${tr('Menú de juego','Game menu')}"><section class="${wide?'wide':''}"><div style="float:right">${back}</div>${html}</section></div>`;}
function render(fade=false){if(title){const v=s||saved;root.innerHTML=`<section class="rpg-stage"><canvas id="world" width="480" height="270" aria-label="${tr('Habitación del laboratorio','Laboratory room')}"></canvas><div class="rpg-title"><div><span class="eyebrow">${tr('UNA PREGUNTA QUE TODAVÍA NO SE APAGA','A QUESTION THAT HAS NOT GONE QUIET')}</span><h1>BEEYOND<br>MARS</h1><img src="assets/gm/spr_bees-0.png" alt="${tr('Abejorro pixelado','Pixel bumblebee')}"><p>${tr('El laboratorio está a punto de cerrar.\nAlguien llama a la puerta.','The laboratory is about to close.\nSomeone knocks at the door.')}</p><div class="actions">${btn(tr('Comenzar','Begin'),'new','primary')}${saved?btn(tr('Continuar','Continue'),'continue'):''}</div><small>${tr('Mover: WASD / flechas · Interactuar: E / espacio\nTambién puedes señalar un objeto para caminar hasta él.','Move: WASD / arrows · Interact: E / space\nYou can also point at an object to walk to it.')}</small><small>Pixel art · ${tr('arte asistido por IA','AI-assisted art')} · v13</small></div></div></section>`;return;}
const phase=s.mission.phase;root.innerHTML=`<section class="rpg-stage ${s.flags.finalKind==='bankrupt'?'bankrupt':''}"><canvas id="world" width="480" height="270" tabindex="0" aria-label="${loc(MAPS[s.map].name)}"></canvas><div class="rpg-top"><span class="place">${loc(MAPS[s.map].name)}${s.map==='ship'?'<br>'+s.mission.day+' / '+E.duration(s.mission)+' '+tr('días','days'):''}</span><div class="actions">${btn(tr('Cuaderno','Notebook'),'journal')}${btn(tr('Accesos','Navigate'),'access')}${btn('Ⅱ','pause')}</div></div><div class="rpg-bottom"><div><span class="rpg-hint" id="near-hint">${tr('WASD / flechas · E para interactuar','WASD / arrows · E to interact')}</span>${s.carry?'<p class="rpg-hint">'+tr('Llevas el cuaderno.','You are carrying the notebook.')+'</p>':''}<div class="rpg-touch">${[['←','a'],['↑','w'],['↓','s'],['→','d']].map(([t,k])=>`<button data-move="${k}" aria-label="${tr('Mover','Move')} ${t}">${t}</button>`).join('')}${btn('E','interact')}</div></div><span class="rpg-ai">AI-assisted sprites · hand-built world</span></div>${fade?'<div class="rpg-wipe"></div>':''}${talk?`<div class="talk-box" role="dialog" aria-label="${esc(talk.who)}">${talk.face==='bee'?'<span class="bee-face" role="img" aria-label="Abejorro"></span>':Number.isInteger(talk.face)?'<span class="portrait role-'+talk.face+'"><img src="assets/gm/spr_crew-0.png" alt="'+PEOPLE[talk.face]+'"></span>':''}<h2>${esc(talk.who)}</h2><p id="talk-text" aria-hidden="true"></p><p class="sr-only">${esc(talk.text)}</p><div class="actions">${talk.choices.map(([label,id],i)=>btn(label,id,i===0?'primary':'')).join('')}</div></div>`:''}${menu?menuHTML():''}${cinema?'<div class="launch-cinema"><div class="countdown" id="launch-count">3</div><img id="launch-rocket" src="assets/gm/spr_rocket-0.png" alt="Aurelia rocket"><div class="launch-smoke"></div><p>'+tr('IGNICIÓN · FONDOS AURELIA','IGNITION · AURELIA FUNDS')+'</p>'+btn(tr('Omitir cinemática','Skip cutscene'),'skip-launch')+'</div>':''}${toastUntil>performance.now()?'<div class="toast-rpg" role="status">'+esc(toastText)+'</div>':''}</section>`;
}
function routeTo(o){const goal={x:o.x+o.w/2,y:Math.min(MAPS[s.map].h-24,o.y+o.h+16)},step=8;const sx=Math.round(s.x/step),sy=Math.round(s.y/step),gx=Math.round(goal.x/step),gy=Math.round(goal.y/step);const key=(x,y)=>x+','+y,seen=new Map([[key(sx,sy),null]]),queue=[[sx,sy]];let found=null;for(let i=0;i<queue.length&&i<10000;i++){const [x,y]=queue[i];if(Math.hypot(x-gx,y-gy)<=1){found=[x,y];break;}for(const [dx,dy]of [[0,1],[0,-1],[1,0],[-1,0]]){const nx=x+dx,ny=y+dy,k=key(nx,ny);if(!seen.has(k)&&!blocked(s,nx*step,ny*step)){seen.set(k,[x,y]);queue.push([nx,ny]);}}}if(!found)return toast(tr('No encuentro un camino libre. Acércate con las flechas.','No clear path found. Move closer with the arrow keys.'));path=[];while(found){path.unshift({x:found[0]*step,y:found[1]*step});found=seen.get(key(...found));}path.shift();walkTo=o;}
function finish(){const a=assessment(s.mission);s.flags.finalKind=a.kind;s.ending=0;changeMap('home',[240,200]);const descriptions={nobel:tr('Años después. En este futuro ficticio, el laboratorio vuelve a llenarse de luz.\nEl teléfono suena. Tus amistades están contigo cuando llega la llamada de Estocolmo.','Years later. In this fictional future, light fills the laboratory again.\nThe phone rings. Your friends are beside you when the call from Stockholm arrives.'),extension:tr('Aurelia deja un contrato sobre el escritorio.\nNo es un premio. Es una prórroga. El laboratorio sigue abierto y la siguiente pregunta ya tiene una página.','Aurelia leaves a contract on the desk.\nIt is not a prize. It is an extension. The laboratory stays open, and the next question already has a page.'),bankrupt:tr('Dos agentes colocan un sello en la puerta.\nEl laboratorio queda en silencio. El contrato terminó.\nConservas el cuaderno: puedes estudiar lo ocurrido y rediseñar la misión.','Two agents seal the door.\nThe laboratory falls silent. The contract is over.\nYou keep the notebook: you can study what happened and redesign the mission.')};say(tr({nobel:'La llamada de Estocolmo',extension:'Supervivencia financiera',bankrupt:'Embargo total'}[a.kind],{nobel:'The call from Stockholm',extension:'Financial survival',bankrupt:'Total foreclosure'}[a.kind]),descriptions[a.kind],[[tr('Revisar los resultados','Review the results'),'results'],[tr('Rediseñar misión','Redesign mission'),'redesign']]);audio.effect(a.kind==='nobel'?'success':'error');}
async function action(a){const [key,id,extra]=a.split(':');if(key!=='fullscreen'){try{await audio.start();}catch{}}audio.effect();if(key==='new'){const g=E.fresh(1,42,0);g.phase='lab';s=newStory(g);title=false;talk=null;menu=null;save();render(true);return;}if(key==='continue'){s=structuredClone(saved);title=false;menu=null;talk=null;render();return;}if(key==='title'){save();title=true;menu=null;talk=null;render();return;}if(key==='skip-launch'){cinema=0;render();return;}if(key==='dismiss')return close();if(['pause','journal','sources','access','results'].includes(key))return open(key);if(key==='interact'){if(!menu&&!talk)interact(nearObject(s));return;}if(key==='walk'){close();routeTo(visibleObjects(s).find(o=>o.id===id));return;}if(key==='fullscreen'){try{document.fullscreenElement?await document.exitFullscreen():await document.documentElement.requestFullscreen();}catch{toast(tr('El navegador no ofrece pantalla completa aquí.','Fullscreen is not available here.'));}return;}
if(key==='take-notebook'){s.carry='notebook';close();save();return;}if(key==='place-notebook'){s.carry=null;s.flags.notebookPlaced=true;memory('notebook');close();checkLetter();return;}if(key==='water-plant'){s.flags.plantWatered=true;memory('plant');close();checkLetter();return;}if(key==='accept-letter'){s.flags.grant=true;memory('letter');say('Lum',tr('Pip. Nim. Eko.\nAntes de construir una nave, tengo que volver a tocar algunas puertas.','Pip. Nim. Eko.\nBefore building a ship, I need to knock on a few doors.'));return;}if(key==='radio-switch'){s.radioOn=!s.radioOn;if(s.radioOn&&s.radioFixed){s.flags.radioFixed=true;audio.effect('success');}save();close();return;}if(key==='radio-fix'){s.radioFixed=true;save();say('Pip',tr('Ahora sí.\nVamos a encenderla.','There.\nLet us turn it on.'),null,0);return;}if(key==='pip-honest'||key==='pip-help'){s.flags.pipHonest=key==='pip-honest';join('Pip');say('Pip',key==='pip-honest'?tr('A mí también.\nPor eso no te dejo hacerlo sin compañía.','I am afraid too.\nThat is why I am not letting you do it alone.'):tr('Entonces vamos.\nMi silla lleva demasiado tiempo vacía.','Then let us go.\nMy chair has been empty for too long.'),null,0);return;}if(key==='water-flowers'){s.flags.flowersWatered=true;save();close();return;}if(key==='watch-bees'){say(tr('Un momento sin medir','A moment without measuring'),tr('Un zumbido pequeño llena el espacio entre ustedes.\nNo has ganado puntos. Aun así, te quedas un poco más.','A small hum fills the space between you.\nYou have earned no points. Still, you stay a little longer.'),null,'bee');return;}
if(key==='message-honest'||key==='message-promise'||key==='correct-message'){s.flags.messageSent=true;s.flags.honest=key!=='message-promise';memory(s.flags.honest?'Eko':'promise');say('Eko',s.flags.honest?tr('Así está bien.\nUna pregunta honesta también puede cruzar el espacio.','That is good.\nAn honest question can cross space too.'):tr('Lo enviaré. Pero me inquieta la palabra “garantizado”.\nSi los datos dicen otra cosa, tendremos que corregirlo.','I will send it. But the word “guaranteed” worries me.\nIf the data says otherwise, we must correct it.'),null,2);return;}
if(key==='role'){s.mission.role=Number(id);save();interact(MAPS.lab.objects.find(o=>o.id===extra));return;}if(key==='item'){const n=E.toggle(s.mission,id);if(n===s.mission)return toast(tr('No hay fondos suficientes, o este turno pertenece a otro rol.','Not enough funding, or this turn belongs to another role.'));s.mission=n;save();render();return;}if(key==='route'){s.mission=E.selectRoute(s.mission,id);save();render();return;}if(key==='launcher'){const n=E.chooseLauncher(s.mission,id);if(n===s.mission)return toast(tr('No alcanza el presupuesto.','The budget is not enough.'));s.mission=n;save();render();return;}if(key==='grant'){const n=E.claim(s.mission,Number(id));if(n===s.mission)return toast(id==='0'?tr('Instala una cámara dentro de masa y potencia de salida.','Install a chamber within mass and departure power.'):tr('Completa la primera revisión y compara las dos rutas.','Finish the first review and compare both routes.'));s.mission=n;save();audio.effect('success');render();return;}
if(key==='launch'){const n=E.launch(s.mission);if(n===s.mission)return open('review');s.mission=n;talk=null;cinema=performance.now();changeMap('ship');say('Lum',tr('Tres. Dos. Uno.\nEl suelo deja de sentirse como suelo.\nPip sujeta la barandilla. Nim mira la cámara. Eko escucha hasta que la voz de casa se vuelve lejana.','Three. Two. One.\nThe floor stops feeling like a floor.\nPip holds the rail. Nim watches the chamber. Eko listens until home sounds far away.'),[[tr('Mirar por la ventana','Look out the window'),'dismiss']]);audio.effect('success');return;}if(key==='advance'){talk=null;s.mission=E.advance(s.mission);save();if(s.mission.phase==='report')verdict();else if(s.mission.flight.pending){audio.effect('error');say('Pip',tr('¿Escuchaste eso?\nRevisemos el panel de sistemas.','Did you hear that?\nLet us check the systems panel.'),null,0);}else render();return;}if(key==='resolve'){s.mission=E.resolve(s.mission,id);save();close();if(s.mission.phase==='report')verdict();return;}if(key==='green'){s.mission=E.startGreen(s.mission);if(s.mission.phase!=='greenhouse')return;menu=null;changeMap('mars');say('Nim',tr('Imaginemos el siguiente experimento, en un hábitat sellado.\nPrimero la cámara. Después el ambiente, las flores y el mensaje de vuelta.','Let us imagine the next experiment, in a sealed habitat.\nFirst the chamber. Then the environment, the flowers and the message home.'),null,1);return;}if(key==='green-choice'){s.mission=E.greenChoice(s.mission,id);close();if(s.mission.green.step>=3&&s.mission.green.lights){s.flags.bloom=true;memory('garden');}save();if(s.mission.phase==='epilogue')say('Lum',tr('El mensaje sale de la antena.\nTardará en llegar. Lo que pase después necesitará años de trabajo.','The message leaves the antenna.\nIt will take time to arrive. What comes next will need years of work.'),[[tr('Años después…','Years later…'),'finish']]);return;}if(key==='finish')return finish();if(key==='ending-next'){s.ending++;save();return ending();}if(key==='redesign'){s.mission=E.redesign(s.mission);s.flags.finalKind=null;s.flags.bloom=false;talk=null;menu=null;changeMap('lab');return;}if(key==='download'){const u=URL.createObjectURL(new Blob([JSON.stringify({story:s,assessment:s.mission.flight?assessment(s.mission):null},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='BeeYondMars-v13.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-do]');if(b)action(b.dataset.do);});document.addEventListener('input',e=>{if(e.target.dataset.volume)audio.set(e.target.dataset.volume,e.target.value);});document.addEventListener('change',e=>{if(e.target.id==='language'){s.lang=e.target.value;document.documentElement.lang=s.lang;save();render();}if(e.target.id==='players'){s.mission.players=Number(e.target.value);save();}if(e.target.id==='time-mode'){s.mission.timer=Number(e.target.value);s.mission.remaining=s.mission.timer;save();}});
document.addEventListener('keydown',e=>{if(title)return;if(e.key==='Escape'){e.preventDefault();return menu||talk?close():open('pause');}if(menu)return;if(talk){if(!e.repeat&&(e.key==='Enter'||e.key===' ')&&talk.choices.length===1){e.preventDefault();action(talk.choices[0][1]);}return;}const k=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright'].includes(k)){e.preventDefault();path=[];walkTo=null;keys.add(k);}if(!e.repeat&&(k==='e'||k===' ')){e.preventDefault();interact(nearObject(s));}});document.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));document.addEventListener('pointerdown',e=>{if(e.target.dataset.move){e.preventDefault();path=[];walkTo=null;keys.add(e.target.dataset.move);e.target.setPointerCapture(e.pointerId);}});document.addEventListener('pointerup',()=>keys.clear());document.addEventListener('pointercancel',()=>keys.clear());window.addEventListener('blur',()=>keys.clear());document.addEventListener('visibilitychange',()=>{keys.clear();if(document.hidden){audio.pause();if(s)save();}else audio.resume();});
root.addEventListener('click',e=>{if(title||talk||menu||e.target.id!=='world')return;const rect=e.target.getBoundingClientRect(),x=(e.clientX-rect.left)/rect.width*480+cam.ox,y=(e.clientY-rect.top)/rect.height*270+cam.oy;const o=visibleObjects(s).find(o=>x>=o.x-10&&x<=o.x+o.w+10&&y>=o.y-20&&y<=o.y+o.h+18);if(o)routeTo(o);});
function frame(now){if(talk){const n=Math.min(talk.text.length,Math.floor((now-talk.start)/18));const p=document.querySelector('#talk-text');if(p)p.textContent=talk.text.slice(0,n);if(n>talk.lastChar&&n%5===0&&audio.blip)audio.blip(Number.isInteger(talk.face)?talk.face:3);talk.lastChar=n;}if(cinema){const age=(now-cinema)/1000;const count=document.querySelector('#launch-count'),rocket=document.querySelector('#launch-rocket');if(count)count.textContent=age<3.6?String(3-Math.floor(age/1.2)):tr('IGNICIÓN','IGNITION');if(rocket)rocket.style.transform='translateY(-'+Math.max(0,age-3.6)*45+'vh)';if(age>7.8){cinema=0;render();}}const dt=Math.min((now-last)/1000,.05);last=now;let walking=false;const drawState=s||saved||newStory(E.fresh());if(!title&&!talk&&!menu&&!document.hidden){let dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),dy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);if(path.length){const p=path[0];dx=p.x-s.x;dy=p.y-s.y;if(Math.hypot(dx,dy)<3){path.shift();dx=dy=0;}else{const length=Math.hypot(dx,dy);dx/=length;dy/=length;}}walking=!!(dx||dy);if(walking){move(s,dx,dy,dt);dir=Math.abs(dx)>Math.abs(dy)?dx<0?1:2:dy<0?3:0;}if(!path.length&&walkTo){const o=walkTo;walkTo=null;if(Math.hypot(s.x-(o.x+o.w/2),s.y-(o.y+o.h+10))<50)interact(o);}saveClock+=dt;if(saveClock>2){save();saveClock=0;}const hint=document.querySelector('#near-hint'),near=nearObject(s);if(hint)hint.textContent=near?'E · '+loc(near.label):tr('WASD / flechas · E para interactuar','WASD / arrows · E to interact');}
if(!title&&!document.hidden&&!talk&&(!menu||menu==='incident')&&s.mission.phase==='voyage'&&s.mission.flight.pending){const before=s.mission.flight.pending;s.mission=E.tick(s.mission,dt);const t=document.querySelector('#timer');if(t)t.textContent=s.mission.timer?Math.ceil(s.mission.remaining)+' s':tr('Sin límite de tiempo','Untimed');if(before!==s.mission.flight.pending||s.mission.phase!=='voyage'){save();menu=null;if(s.mission.phase==='report')verdict();else say('Pip',tr('Se activó la respuesta autónoma.\nQuedó anotada en la bitácora.','The autonomous response activated.\nIt is recorded in the log.'),null,0);}}
const canvas=document.querySelector('#world');if(canvas)cam=drawWorld(canvas,drawState,now,dir,walking);if(audio.setScene)audio.setScene(cinema?'launch':title?'home':s.flags.finalKind||(s.mission.flight?.pending&&s.mission.phase==='voyage'?'emergency':s.map));if(toastText&&now>toastUntil){toastText='';document.querySelector('.toast-rpg')?.remove();}requestAnimationFrame(frame);}
render();requestAnimationFrame(frame);
